int main(){

    char str[STR_SIZE],ch;
    int i;
    int c_count = 0;
    int w_count = 0;
    int s_count = 0;
    int l_count = 0;

    int in_word = 0;

    printf("Enter the string, enter ` when done enterin -> ") ;
    for(i = 0 ; i < STR_SIZE-1;i++){
        ch =  getchar();
        if (ch == '`'){
            break;
        }
        str[i] = ch;
    }
    str[i] ='\0';
    for (int j = 0; j < i; j++) {
        c_count++;

        if (str[j] == ' ') {
            s_count++;
        }

        if (str[j] == '\n') {
            l_count++;
        }

        if (str[j] != ' ' && str[j] != '\n' && str[j] != '\t') {
            if (in_word == 0) {
                w_count++;
                in_word = 1;
            }
        } else {
            in_word = 0;
        }
    }

    printf("The string you entered:\n%s\n", str);
    printf("Characters: %d\n", c_count);
    printf("Words: %d\n", w_count);
    printf("Spaces: %d\n", s_count);
    printf("Lines: %d\n", l_count + (i > 0 && str[i - 1] != '\n'));

    return 0;
}

// Strings -> Q 21 : Print all permutations of a string, e.g., "ABCDE".


#include <stdio.h>
#include <string.h>
#define STR_SIZE 100


void permute(char arr[], int start, int n) {
    if (start == n) {
        for (int i = 0; i < n; i++) {
            printf("%c ", arr[i]);
        }
        printf("\n");
        return;
    }

    for (int i = start; i < n; i++) {
        // swap 
        char temp = arr[start];
        arr[start] = arr[i];
        arr[i] = temp;

        permute(arr, start + 1, n);

        // undo it 
        temp = arr[start];
        arr[start] = arr[i];
        arr[i] = temp;
    }
}



int main(){

    char str[STR_SIZE],ch;
    int i;

    printf("Enter the string -> ") ;
    for(i = 0 ; i < STR_SIZE-1;i++){
        ch =  getchar();
        if (ch == '\n'){
            break;
        }

        str[i] = ch;
    }
    str[i] ='\0';


    printf("The string you entered -> %s\n",str);
    permute(str,0,i);

    return 0;
}
